const char setup_portal_css[] =
    ":root{color-scheme:light;--green:#08783e;--deep:#064d2b;--gold:#d9a928;--ink:#173127;--muted:#61756b;--line:#dce7e1;--pale:#f4faf6}"
    "*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,#e4f5eb 0,transparent 42%),linear-gradient(135deg,#f4faf6,#fdf9ed);color:var(--ink);font:16px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}"
    "main{min-height:100vh;display:grid;place-items:center;padding:22px}.card{width:min(660px,100%);background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:0 18px 60px #0b4e2920;padding:30px}"
    "header{display:flex;gap:18px;align-items:center;padding-bottom:20px;border-bottom:4px solid var(--gold)}.logo{display:block;width:140px;height:auto;object-fit:contain}"
    "h1{margin:2px 0 0;color:var(--deep);font-size:1.75rem}.eyebrow{margin:0;color:var(--green);font-size:.68rem;font-weight:800;letter-spacing:.08em}.sub{margin:3px 0;color:var(--muted)}"
    ".steps{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:20px 0 0;padding:0;list-style:none;color:var(--muted);font-size:.76rem;font-weight:750;text-align:center}.steps li{padding:8px 5px;border-radius:9px;background:#f4f6f5}.steps span{display:inline-grid;place-items:center;width:22px;height:22px;margin-right:4px;border-radius:50%;background:#dfe7e3;color:var(--deep)}.steps .done,.steps .active{color:var(--deep);background:var(--pale)}.steps .done span{background:var(--green);color:#fff}.steps .active{outline:2px solid #d9a92866}.steps .active span{background:var(--gold);color:#332709}"
    ".notice{margin:18px 0;padding:12px 14px;border-left:4px solid var(--gold);background:#fff9e7;border-radius:8px;font-size:.9rem}label{display:block;margin:14px 0 6px;font-weight:750}.row{display:grid;grid-template-columns:1fr auto;gap:9px}.password-row{display:grid;grid-template-columns:1fr auto;gap:9px}"
    "input,select,button{width:100%;min-height:46px;border-radius:10px;border:1px solid #b8cbc1;padding:10px 12px;font:inherit}input:focus,select:focus,button:focus-visible{outline:3px solid #08783e25;border-color:var(--green)}button{margin-top:20px;border:0;background:var(--green);color:#fff;font-weight:800;cursor:pointer}button:disabled{cursor:wait;opacity:.62}.secondary,.password-toggle{width:auto;margin:0;background:#edf6f1;color:var(--deep);border:1px solid #b8cbc1}.password-toggle{min-width:70px}.check{display:flex;align-items:center;gap:8px;font-weight:500}.check input{width:18px;min-height:18px}.hidden{display:none}.hint{margin:8px 0 0;color:var(--muted);font-size:.82rem}"
    "#status{display:none;margin-top:18px;padding:13px 14px;border-radius:10px;background:#edf6f1;border:1px solid #cde4d7}#status.show{display:block}#status.error{background:#fff0ef;color:#8c1d18;border-color:#f1c8c4}footer{margin-top:24px;padding-top:16px;border-top:1px solid var(--line);text-align:center;color:var(--muted);font-size:.78rem}@media(max-width:520px){.card{padding:20px}header{align-items:flex-start}.logo{width:105px}h1{font-size:1.4rem}.steps{font-size:.68rem}.steps span{display:none}.row{grid-template-columns:1fr}.secondary{width:100%}}";

const char setup_portal_js[] =
    "const $=s=>document.querySelector(s),status=$('#status'),form=$('#wifi-form'),network=$('#network');let poll;"
    "function say(message,error=false){status.textContent=message;status.className='show'+(error?' error':'')}"
    "function disableForm(value){form.setAttribute('aria-busy',String(value));form.querySelectorAll('input,select,button').forEach(x=>x.disabled=value)}"
    "function signal(rssi){return rssi>=-55?'Excellent':rssi>=-67?'Good':rssi>=-75?'Fair':'Weak'}"
    "async function scan(){say('Scanning nearby compatible networks…');$('#scan').disabled=true;try{const r=await fetch('/api/networks',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.message||'Scan failed');network.innerHTML='<option value=\"\">Select a 2.4 GHz network</option>';for(const n of d.networks){const o=document.createElement('option');o.value=n.ssid;o.textContent=`${n.ssid} · ${n.security||'WPA2'} · ${signal(n.rssi)}`;network.append(o)}say(d.networks.length?'Choose a network and enter its password.':'No compatible network found. You can enter a hidden SSID.',!d.networks.length)}catch(e){say(e.message||'Network scan could not complete.',true)}finally{$('#scan').disabled=false}}"
    "$('#scan').onclick=scan;$('#toggle-password').onclick=e=>{const p=$('#wifi-password'),show=p.type==='password';p.type=show?'text':'password';e.currentTarget.textContent=show?'Hide':'Show';e.currentTarget.setAttribute('aria-pressed',String(show))};"
    "$('#hidden').onchange=e=>{for(const id of ['#manual-label','#manual-ssid'])$(id).classList.toggle('hidden',!e.target.checked);network.required=!e.target.checked;$('#manual-ssid').required=e.target.checked};"
    "async function check(){try{const r=await fetch('/api/status',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.message||'Status unavailable');say(d.message,d.state==='failed');if(d.state==='failed'){clearInterval(poll);disableForm(false)}else if(d.state==='saved'){clearInterval(poll)}}catch(e){say('The device is switching networks. This setup access point may close shortly.')}}"
    "form.onsubmit=async e=>{e.preventDefault();const hidden=$('#hidden').checked,ssid=hidden?$('#manual-ssid').value.trim():network.value,password=$('#wifi-password').value;if(!ssid)return say('Select or enter a Wi-Fi network.',true);disableForm(true);say('Testing the new network for up to 30 seconds…');try{const r=await fetch('/api/network',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:$('#csrf').value,ssid,password})}),d=await r.json();if(!r.ok)throw Error(d.message||'Unable to save');poll=setInterval(check,1500);check()}catch(e){say(e.message||'Unable to start the network test.',true);disableForm(false)}};scan();";
